INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(11488, 'plPL', 'Taras Magistrów', 'Witaj przy Słonecznej Studni, $N. Rozgość się i pomagaj, jak tylko możesz – roboty jest mnóstwo!$b$bJa? Owszem, mam pewną sprawę do załatwienia, ale nie jestem pewien, czy temu podołasz.$b$bMieliśmy na Tarasie Magistrów wtyczkę, która zbierała dla nas informacje. Ostatnio przestał się meldować i zaczynam się niepokoić.$b$bTaras leży tuż za wzniesieniem na wschodzie. Informacje, które zbierał, są kluczowe dla naszej misji.$b$bMyślisz, że dasz sobie radę?', 'Egzarcha Larethor z Placu Zbornego Straceńczego Słońca chce, żebyś $gprzeszukał:przeszukała; Taras Magistrów i $godnalazł:odnalazła; Tyritha, szpiega krwawych elfów.', '', '', '', '', '', '', 0),
(11492, 'plPL', 'Trudny do zabicia', 'Witajcie przy Słonecznej Studni, śmiertelnicy. Przybywacie w samą porę.$b$bJak sami widzieliście, siły Legionu pracują niestrudzenie, naginając moc Słonecznej Studni do swoich nikczemnych celów.$b$bKael\'thas powstał z popiołów klęski i znów im przewodzi. Odnajdźcie go, śmiertelnicy. Trzeba go ponownie powstrzymać.$b$bInne, równie pilne sprawy wymagają mojej natychmiastowej uwagi. Los Kaela zostawiam wam. Nie zawiedźcie.$b$bJeśli szczęście dopisze, jeszcze się spotkamy.', 'Kalegos poprosił cię, żebyś $gpokonał:pokonała; Kael\'thasa na Tarasie Magistrów. Masz zabrać głowę Kaela i zameldować się u Larethora na Placu Zbornym Straceńczego Słońca.', '', 'Wróć do egzarchy Larethora na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11496, 'plPL', 'Osłony Sanktuarium', 'Naszym pierwszym celem jest zdobycie Sanktuarium Słonecznego Zasięgu. Gdy je zabezpieczymy, będziemy mogli użyć jego energii, by otworzyć portal z Shattrath.$B$BSanktuarium zaroiło się od Nędznych – dawnych krwawych elfów, którzy zdegenerowali się w bezmyślne skorupy dawnych siebie. Jego zabezpieczenia normalnie nie dopuściłyby do takiego wtargnięcia, ale Nędzni wykradli źródła mocy z osłon ochronnych.$B$BWytrop Nędznych i zabierz pozostałości many, które noszą przy sobie. Użyj ich, by zasilić osłony sanktuarium.', 'Kapitan Theris Serce Świtu z Placu Zbornego Straceńczego Słońca chce, żebyś $gzdobył:zdobyła; 4 pozostałości many od nędznych biesów i nędznych pożeraczy, a następnie $gużył:użyła; ich do zasilenia jednej z kryształowych osłon otaczających Sanktuarium Słonecznego Zasięgu na wschodzie.', 'Zasil kryształową osłonę', 'Wróć do kapitana Therisa Serca Świtu na Placu Zbornym Straceńczego Słońca na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11523, 'plPL', 'Uzbrój osłony!', 'Udało nam się reaktywować kryształowe osłony wokół sanktuarium, ale po co na tym poprzestawać? Zbudujemy zabezpieczenia wokół pozostałych budowli, lecz Nędzni są uparci i wciąż wykradają moc z kryształowych osłon.$B$BWytrop ich i zabierz pozostałości many, które noszą przy sobie. Użyj ich, by zasilić osłony – od tego zależy bezpieczeństwo naszej operacji.', 'Kapitan Theris Serce Świtu z Placu Zbornego Straceńczego Słońca chce, żebyś $gzdobył:zdobyła; 4 pozostałości many od nędznych biesów i nędznych pożeraczy, a następnie $gużył:użyła; ich do zasilenia jednej z kryształowych osłon otaczających budowle w Słonecznym Zasięgu.', 'Zasil kryształową osłonę', 'Wróć do kapitana Therisa Serca Świtu na Placu Zbornym Straceńczego Słońca na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11524, 'plPL', 'Nieobliczalne zachowanie', 'Brakuje nam ludzi, by zdobyć Sanktuarium w Słonecznym Zasięgu, ale mam plan, który przechyli szalę na naszą korzyść.$B$BSwobodna energia Słonecznej Studni sprawiła, że wartownicy patrolujący wyspę działają wadliwie. Kryształowe rdzenie, które sterują ich zachowaniem, są uszkodzone nie do naprawienia.$B$BWykonałam nowe kryształy, które poddadzą ich naszej kontroli – umieść je we wnętrzu pokonanych wartowników. Przyda nam się każda pomoc.', 'Obrończyni Xayann z Placu Zbornego Straceńczego Słońca chce, żebyś $gumieścił:umieściła; dostrojone kryształowe rdzenie w 5 pokonanych rozregulowanych wartownikach, by przeciągnąć ich na naszą stronę.', '', 'Wróć do obrończyni Xayann na Placu Zbornym Straceńczego Słońca na Wyspie Quel\'Danas.', 'Przeprogramowany wartownik rozmieszczony', '', '', '', 0),
(11525, 'plPL', 'Kolejne przeprogramowania', 'Mój plan wymiany uszkodzonych kryształów w rozregulowanych wartownikach zakończył się sukcesem. Z ich pomocą zdobyliśmy Sanktuarium Słonecznego Zasięgu.$B$BWykonałam nowe kryształy, które poddadzą naszej kontroli kolejnych z nich – umieść je we wnętrzu pokonanych wartowników. Po przeprogramowaniu roześlemy ich w inne miejsca.', 'Obrończyni Xayann z Placu Zbornego Straceńczego Słońca chce, żebyś $gumieścił:umieściła; dostrojone kryształowe rdzenie w 5 pokonanych rozregulowanych wartownikach, by przeciągnąć ich na naszą stronę.', '', 'Wróć do obrończyni Xayann na Placu Zbornym Straceńczego Słońca na Wyspie Quel\'Danas.', 'Przeprogramowany wartownik rozmieszczony', '', '', '', 0),
(11532, 'plPL', 'Dywersja na Trupiej Bliźnie', 'Legion ruszy na nas, gdy tylko zwolnią się jego siły na południu. Na razie zajmuje je Plaga na Trupiej Bliźnie. Nie potrwa to jednak długo.$B$BChcę, żebyś $gpoleciał:poleciała; smoczym jastrzębiem nad Bliznę i tymi tajemnymi ładunkami $gprzerzedził:przerzedziła; szeregi demonów.$B$BJeśli wszystko pójdzie dobrze, nawet nie zauważą, jak odbieramy zbrojownię sługusom Kaela. Kiedy będziesz $ggotów:gotowa; do lotu, porozmawiaj z Ayrenem, mistrzem smoczych jastrzębi w zachodniej części portu.', 'Magini bojowa Arynna chce, żebyś $gporozmawiał:porozmawiała; z Ayrenem Chmurołamaczem, gdy będziesz $ggotów:gotowa; do lotu nad Trupią Blizną. Na miejscu użyj tajemnych ładunków, by zabić 2 nadrządców otchłani, 3 eredarskich czarowników i 12 egzekutorów gniewu.', '', 'Wróć do magini bojowej Arynny w Sanktuarium Słonecznego Zasięgu na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11533, 'plPL', 'Naloty muszą trwać', 'Zdobyliśmy zbrojownię dzięki naszym atakom z powietrza na siły Legionu na Trupiej Bliźnie.$B$BPrawdę mówiąc, poszło tak dobrze, że będziemy kontynuować naloty. Weź te tajemne ładunki i użyj ich przeciwko wrogim siłom.$B$BKiedy będziesz $ggotów:gotowa; do lotu, porozmawiaj z Ayrenem Chmurołamaczem w Porcie Słonecznego Zasięgu.', 'Magini bojowa Arynna chce, żebyś $gporozmawiał:porozmawiała; z Ayrenem Chmurołamaczem, gdy będziesz $ggotów:gotowa; do lotu nad Trupią Blizną. Na miejscu użyj tajemnych ładunków, by zabić 2 nadrządców otchłani, 3 eredarskich czarowników i 12 egzekutorów gniewu.', '', 'Wróć do magini bojowej Arynny w Sanktuarium Słonecznego Zasięgu na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11535, 'plPL', 'Przygotowania', 'Zaopatrzenie jest już w drodze, a przynajmniej tak mi mówią.$b$bTak czy inaczej, nie możemy sobie pozwolić na czekanie z nadzieją, że pomoc dotrze, zanim nasza ofensywa utknie. Musimy jak najlepiej wykorzystać to, co mamy.$b$bJa potrzebuję rudy, żeby wykuć kowadło i zacząć ulepszać naszą broń i pancerze.$b$bNa wybrzeżu na wschód stąd grupa nag zbiera rudę i składa ją w skrzyniach do wysyłki dla Legionu.$b$bOdebranie im tej rudy pomoże naszej sprawie na więcej niż jeden sposób...', 'Kowalka Hauthaa w Zbrojowni Słonecznego Zasięgu chce, żebyś $gzabijał:zabijała; siepaczy Mrocznego Grzbietu na wschodzie i ich kluczami $gotworzył:otworzyła; skrzynie, z których masz zabrać trzy bryły rudy.', '', 'Wróć do kowalki Hauthaa na Wybrzeżu Zielonoskrzelnych na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11536, 'plPL', 'Nie przestawaj teraz...', 'Teraz, gdy mamy kowadło, mogę naprawdę zabrać się do pracy.$b$bBez względu na to, ile zaopatrzenia dostaniemy, zawsze znajdę zastosowanie dla rudy żelaza Mrocznego Grzbietu. Jeśli mamy tu odnieść sukces, potrzebujemy stałych dostaw broni i pancerzy.$b$bNa wybrzeżu na wschód stąd jest grupa nag. Zbierają rudę i składają ją w skrzyniach do wysyłki dla Legionu. Odebranie im tej rudy pomoże naszej sprawie na więcej niż jeden sposób...', 'Kowalka Hauthaa w Zbrojowni Słonecznego Zasięgu chce, żebyś $gzabijał:zabijała; siepaczy Mrocznego Grzbietu na wschodzie i ich kluczami $gotworzył:otworzyła; skrzynie, z których masz zabrać trzy bryły rudy.', '', 'Wróć do kowalki Hauthaa na Wybrzeżu Zielonoskrzelnych na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11537, 'plPL', 'Bitwa musi trwać', 'Musimy dalej pokonywać i demoralizować armie Legionu.$B$BEmisariusze nienawiści to szturmowcy Legionu, wysyłani, by wzmacniać jego kluczowe pozycje. Wróg skupia się wokół nich, bo boi się ich bardziej niż nas.$B$BDziś to zmienimy. Weź ten sztandar i zabijaj demony Legionu. Gdy spotkasz emisariusza, zabij go i nadziej na drzewce.', 'Zwiastun Inuuro chce, żebyś $gzabił:zabiła; 6 demonów Płonącego Legionu oraz emisariusza nienawiści na Placu Świtu. Użyj sztandaru Straceńczego Słońca, by nadziać zwłoki emisariusza nienawiści.', '', 'Wróć do zwiastuna Inuuro w Sanktuarium Słonecznego Zasięgu na Wyspie Quel\'Danas.', 'Emisariusz nienawiści nadziany', '', '', '', 0),
(11538, 'plPL', 'Bitwa o Zbrojownię Słonecznego Zasięgu', 'Płonący Legion trzyma Zbrojownię Słonecznego Zasięgu, która ma dla naszej operacji znaczenie taktyczne. Dopóki jego morale jest wysokie, nie wydrzemy mu tego budynku.$B$BEmisariusze nienawiści to szturmowcy Legionu, wysyłani, by wzmacniać jego kluczowe pozycje. Wróg skupia się wokół nich, bo boi się ich bardziej niż nas.$B$BDziś to zmienimy. Weź ten sztandar i zabijaj demony Legionu. Gdy spotkasz emisariusza, zabij go i nadziej na drzewce.', 'Zwiastun Inuuro chce, żebyś $gzabił:zabiła; 6 demonów Płonącego Legionu oraz emisariusza nienawiści na Placu Świtu lub w Zbrojowni Słonecznego Zasięgu. Użyj sztandaru Straceńczego Słońca, by nadziać zwłoki emisariusza nienawiści.', '', 'Wróć do zwiastuna Inuuro w Sanktuarium Słonecznego Zasięgu na Wyspie Quel\'Danas.', 'Emisariusz nienawiści nadziany', '', '', '', 0),
(11539, 'plPL', 'Zdobycie portu', 'Jedna z najbardziej elitarnych formacji Kaela, armia Ostrza Świtu, stacjonuje w Porcie Słonecznego Zasięgu i w Wiosce Gwiazdy Zarannej.$B$BPort ma kluczowe znaczenie dla naszych planów, więc każda strata, jaką zadasz Ostrzu Świtu, będzie ogromną pomocą. Kael\'thas pożałuje dnia, w którym odwrócił się od własnego ludu i stanął po stronie Płonącego Legionu.', 'Magister Ilastar w Zbrojowni Słonecznego Zasięgu chce, żebyś $gzabił:zabiła; 6 przywoływaczy Ostrza Świtu, 6 Krwawych Rycerzy Ostrza Świtu i 3 strzelców Ostrza Świtu.', '', 'Wróć do magistra Ilastara w Zbrojowni Słonecznego Zasięgu na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11540, 'plPL', 'Zmiażdżyć Ostrze Świtu', 'Wyparliśmy armię Ostrza Świtu z Portu Słonecznego Zasięgu. Cały Słoneczny Zasięg jest nasz. A jednak... coś mi nie daje spokoju.$B$BChcę, żebyś $gudał:udała; się do Wioski Gwiazdy Zarannej, na zachód stąd, i $gzabił:zabiła; wszystkich ocalałych wojowników Ostrza Świtu. Przypieczętowali swój los, gdy poszli za Kaelem w to miejsce.', 'Magister Ilastar w Zbrojowni Słonecznego Zasięgu chce, żebyś $gzabił:zabiła; 6 przywoływaczy Ostrza Świtu, 6 Krwawych Rycerzy Ostrza Świtu i 3 strzelców Ostrza Świtu.', '', 'Wróć do magistra Ilastara w Zbrojowni Słonecznego Zasięgu na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11541, 'plPL', 'Zamęt na Wybrzeżu Zielonoskrzelnych', 'Nagi zajęły Wybrzeże Zielonoskrzelnych na południowym wschodzie. Ich samice, syreny Mrocznego Grzbietu, zniewalają magią miejscowe murloki.$B$BMoim zadaniem jest dopilnować, by cokolwiek nagi tam knują, zostało pokrzyżowane. I tu wkraczasz ty.$B$BChcę, żebyś $godebrał:odebrała; samicom nag kule kontroli i $grzucał:rzucała; je w pobliżu niewolników z Zielonoskrzelnych – kula się rozbije, a murloki odzyskają wolność.$B$BCoś mi mówi, że murloki wpadną w szał i zwrócą się przeciwko swoim panom.', 'Kapitan Valindria chce, żebyś $guwolnił:uwolniła; 10 niewolników z Zielonoskrzelnych. Gdy to zrobisz, wróć do niej na pokład Dumy Srebrnej Luny w Porcie Słonecznego Zasięgu.', '', 'Wróć do kapitan Valindrii w Porcie Słonecznego Zasięgu na Wyspie Quel\'Danas.', 'Uwolniony niewolnik z Zielonoskrzelnych', '', '', '', 0),
(11542, 'plPL', 'Przechwycić posiłki', 'Chcemy umocnić naszą kontrolę nad Słonecznym Zasięgiem, zdobywając teraz port. Niestety flota z rezerwistami Ostrza Świtu płynie tam, by wzmocnić siły Kaela.$B$BWeź ten olej i zdobądź smoczego jastrzębia od Ayrena Chmurołamacza. Powinno ci się udać podlecieć na tyle blisko, by dosięgnąć żagli statków – gdy będziesz dość blisko, podpal je.$B$BWyląduj na jednym ze statków i zaatakuj rezerwistów. Z płonącymi żaglami nie zdołają się porządnie bronić.', 'Obrońca Kaalan w Zbrojowni Słonecznego Zasięgu chce, żebyś $gporozmawiał:porozmawiała; z Ayrenem Chmurołamaczem i $gprzeleciał:przeleciała; nad flotą posiłków Ostrza Świtu. Podczas lotu użyj płonącego oleju, by podpalić żagle statków, a po wylądowaniu zabij 6 rezerwistów Ostrza Świtu.', '', 'Wróć do obrońcy Kaalana w Zbrojowni Słonecznego Zasięgu na Wyspie Quel\'Danas.', 'Spalone żagle „Sin\'loren”', 'Spalone żagle „Krwawej Przysięgi”', 'Spalone żagle „Pogoni za Świtem”', '', 0),
(11543, 'plPL', 'Trzymać wroga z dala', 'Udało nam się zdobyć cały Słoneczny Zasięg. Niestety flota z rezerwistami Ostrza Świtu płynie, by odbić port.$B$BWeź ten olej i zdobądź smoczego jastrzębia od Ayrena Chmurołamacza. Powinno ci się udać podlecieć na tyle blisko, by dosięgnąć żagli statków – gdy będziesz dość blisko, podpal je.$B$BWyląduj na jednym ze statków i zaatakuj rezerwistów. Z płonącymi żaglami nie zdołają się porządnie bronić.', 'Obrońca Kaalan w Zbrojowni Słonecznego Zasięgu chce, żebyś $gporozmawiał:porozmawiała; z Ayrenem Chmurołamaczem i $gprzeleciał:przeleciała; nad flotą posiłków Ostrza Świtu. Podczas lotu użyj płonącego oleju, by podpalić żagle statków, a po wylądowaniu zabij 6 rezerwistów Ostrza Świtu.', '', 'Wróć do obrońcy Kaalana w Zbrojowni Słonecznego Zasięgu na Wyspie Quel\'Danas.', 'Spalone żagle „Sin\'loren”', 'Spalone żagle „Krwawej Przysięgi”', 'Spalone żagle „Pogoni za Świtem”', '', 0),
(11545, 'plPL', 'Datek na szczytny cel', 'Odebraliśmy wrogowi Słoneczny Zasięg, a ostateczne zwycięstwo jest na wyciągnięcie ręki. Cena była wysoka – wielu dzielnych wojowników oddało życie, byśmy mogli to osiągnąć.$B$BChcę dopilnować, by ci, którzy polegli w walce, nie zostali zapomniani. Proszę cię, zastanów się przez chwilę nad datkiem na fundusz pamięci. Całe pozostałe złoto trafi do wdów i sierot po poległych.', 'Anachoretka Ayuri w Słonecznym Zasięgu na Wyspie Quel\'Danas chce, żebyś $gprzekazał:przekazała; 10 sztuk złota.', '', '', '', '', '', '', 0),
(11546, 'plPL', 'Interes otwarty', 'Witaj, $N.$b$bNa wiele sposobów mogę ci pomóc w twoich tutejszych staraniach.$b$bNa przykład niedawno odkryłam przepis na wyjątkowy eliksir.$b$bKrwawojagoda rośnie dziko w wielu krainach Azeroth i od dawna uchodziła jedynie za uciążliwy chwast. Dowiedziałam się jednak, że wystawiona na moc Słonecznej Studni roślina zyskuje szczególne właściwości, które można wydestylować i wypić, by wzmocnić swoje zdolności.$b$bPrzynieś mi próbkę z pobliskich krzewów, a pokażę ci, o co mi chodzi.', 'Mar\'nah w Porcie Słonecznego Zasięgu chce, żebyś $gzebrał:zebrała; 5 krwawojagód z krzewów rosnących na Quel\'Danas.', '', 'Wróć do Mar\'nah w Porcie Słonecznego Zasięgu na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11547, 'plPL', 'Poznaj swoje linie mocy', 'Darmozjady!$b$bWszyscy chcecie wszystkiego od razu – nigdy nie myśląc o wysiłku, jakiego wymaga stworzenie nawet najprostszego portalu.$b$bMoże odrobina edukacji wzbudzi w was choć trochę wdzięczności za moje nieustanne wysiłki.$b$bWeź ten kryształ. Dostrój go do Krwawego kryształu na zachodzie, do portalu na Placu Świtu tuż na południe stąd oraz do świątyni nag na Wybrzeżu Zielonoskrzelnych na południowym wschodzie.$b$bMoże wtedy docenisz te swoje cenne translokacje...', 'Astromanta Darnarian w Sanktuarium Słonecznego Zasięgu chce, żebyś $gużył:użyła; kryształu astromanty przy Krwawym krysztale, przy portalu na Placu Świtu i przy świątyni nag na Wybrzeżu Zielonoskrzelnych.', '', 'Wróć do astromanty Darnariana w Sanktuarium Słonecznego Zasięgu na Wyspie Quel\'Danas.', 'Odczyt z portalu pobrany', 'Odczyt ze świątyni pobrany', 'Odczyt z Krwawego kryształu pobrany', '', 0),
(11548, 'plPL', 'Twoje dalsze wsparcie', 'Zbudowaliśmy pomnik ku czci poległych w bitwie. To jednak marna pociecha dla rodzin, które straciły bliskich.$B$BZbieram datki na pomoc sierotom i małżonkom naszych bohaterów wojennych. Jeśli możesz przeznaczyć choćby niewielką kwotę, bardzo nam to pomoże.', 'Anachoretka Ayuri w Słonecznym Zasięgu na Wyspie Quel\'Danas chce, żebyś $gprzekazał:przekazała; 10 sztuk złota.', '', '', '', '', '', '', 0),
(11549, 'plPL', 'Hojny dobroczyńca', 'Tak wiele dla nas $gzrobiłeś:zrobiłaś;, $N. Bardzo cenimy twoją pomoc.$B$BByć może $gzauważyłeś:zauważyłaś; starania anachoretki Ayuri na zewnątrz. Ma wielkie serce i potrafi przekonywać, ale datki nie sięgają kwoty, której się spodziewała.$B$BJeśli wniesiesz duży wkład w jej sprawę, dopilnuję, by wieść o twoich czynach w tej wojnie rozeszła się szeroko. Co ty na to?', 'Anachoreta Kairthos chce, żebyś $gprzekazał:przekazała; 1000 sztuk złota na wsparcie starań anachoretki Ayuri. Po wykonaniu tego zadania będziesz $gznany:znana; jako $N ze Straceńczego Słońca.', '', '', '', '', '', '', 0),
(11551, 'plPL', 'Agamath, Pierwsza Brama', '', '', '', 'Wróć do arcymaga Ne\'thula na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11552, 'plPL', 'Rohendor, Druga Brama', '', '', '', 'Wróć do arcymaga Ne\'thula na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11553, 'plPL', 'Archonisus, Ostatnia Brama', '', '', '', 'Wróć do arcymaga Ne\'thula na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11554, 'plPL', 'Przyjaciel na linii frontu', '', '', '', '', '', '', '', '', 0),
(11555, 'plPL', 'Szanowany przez sojuszników', '', '', '', '', '', '', '', '', 0),
(11556, 'plPL', 'Czczony na polu bitwy', '', '', '', '', '', '', '', '', 0),
(11557, 'plPL', 'Wywyższony pośród wszystkich wojowników', '', '', '', '', '', '', '', '', 0),
(24522, 'plPL', 'Podróż do Słonecznej Studni', 'Zanieś Quel\'Delar do Słonecznej Studni tak szybko, jak to możliwe, $N. Zaufaj słowom Uthera, gdy mówi, że nie zawsze zdołasz zapanować nad ostrzem, póki podlega ono złu wpływu Króla Lisza. Musisz udać się na Wyspę Quel\'Danas i tam uzyskać wstęp do samej Słonecznej Studni, gdzie możesz oczyścić miecz.$B$BStrażnicy Słonecznej Studni nie wpuszczą cię tak po prostu, więc musisz odnaleźć Haldurona Jasnoskrzydłego, który będzie tam wizytował straże.', 'Porozmawiaj z Halduronem Jasnoskrzydłym przy wejściu na Płaskowyż Słonecznej Studni na Wyspie Quel\'Danas.', '', 'Wróć do Haldurona Jasnoskrzydłego w Wiosce Gwiazdy Zarannej na Wyspie Quel\'Danas.', '', '', '', '', 0),
(24535, 'plPL', 'Thalorien Szukający Świtu', 'Jeśli naprawdę nosisz Quel\'Delar, $N, być może zdołam wpuścić cię do Słonecznej Studni. Jeśli znasz historię tego ostrza, pamiętasz, że dzierżył je Thalorien Szukający Świtu, broniąc Słonecznej Studni przed Plagą. Poległ tam, gdzie dziś ciągnie się Trupia Blizna, zyskując dla swoich ludzi czas na przygotowania. Jego szczątki znajdziesz w pobliżu południowego krańca Trupiej Blizny na tej wyspie. Odwiedź je, a jeśli jego duch udzieli ci błogosławieństwa, pozwolę ci wejść do Słonecznej Studni.', 'Odwiedź szczątki Thaloriena Szukającego Świtu i uzyskaj jego błogosławieństwo, by dzierżyć Quel\'Delar.', '', 'Wróć do Haldurona Jasnoskrzydłego w Wiosce Gwiazdy Zarannej na Wyspie Quel\'Danas.', 'Uzyskane błogosławieństwo Thaloriena', '', '', '', 0),
(24553, 'plPL', 'Oczyszczenie Quel\'Delara', 'Przyznaję, wątpiłem, że naprawdę $gprzekułeś:przekułaś; Quel\'Delar, i nie spodziewałem się, że duch Thaloriena ci się objawi. Nie możesz pojąć, co dla mnie i dla reszty mojego ludu znaczy odzyskanie Quel\'Delara.$B$BZgodnie z obietnicą wpuszczę cię do Słonecznej Studni, a w środku zastaniesz przywódców Srebrnej Luny. Zanieś miecz do komnaty Słonecznej Studni i zanurz go. Ostrze zwiąże się z tobą. Gdy to nastąpi, zanieś je Caladisowi Jasnowłóczni przy Spoczynku Quel\'Delara.', 'Zanurz Zahartowany Quel\'Delar w Słonecznej Studni. Gdy będziesz $ggotów:gotowa; wejść na Płaskowyż Słonecznej Studni, porozmawiaj ze Strażnikiem Słonecznej Studni.', '', 'Wróć do Caladisa Jasnowłóczni przy Spoczynku Quel\'Delara w Lodowej Koronie.', '', '', '', '', 0),
(24562, 'plPL', 'Podróż do Słonecznej Studni', 'Zanieś Quel\'Delar do Słonecznej Studni tak szybko, jak to możliwe, $N. Zaufaj słowom Uthera, gdy mówi, że nie zawsze zdołasz zapanować nad ostrzem, póki podlega ono złu wpływu Króla Lisza. Musisz udać się na Wyspę Quel\'Danas i tam uzyskać wstęp do samej Słonecznej Studni, gdzie możesz oczyścić miecz.$B$BStrażnicy będą próbowali nie dopuścić cię na Płaskowyż Słonecznej Studni, ale daj się poznać Halduronowi Jasnoskrzydłemu, który będzie tam wizytował straże.', 'Porozmawiaj z Halduronem Jasnoskrzydłym przy wejściu na Płaskowyż Słonecznej Studni na Wyspie Quel\'Danas.', '', 'Wróć do Haldurona Jasnoskrzydłego w Wiosce Gwiazdy Zarannej na Wyspie Quel\'Danas.', '', '', '', '', 0),
(24563, 'plPL', 'Thalorien Szukający Świtu', 'To ty współpracujesz z Myralionem Słonecznym Żarem, prawda? Znam sposób, by sprawdzić ten miecz.$B$BJeśli znasz historię tego ostrza, pamiętasz, że dzierżył je Thalorien Szukający Świtu, broniąc Słonecznej Studni przed Plagą. Poległ tam, gdzie dziś ciągnie się Trupia Blizna, zyskując dla swoich ludzi czas na przygotowania. Jego szczątki znajdziesz w pobliżu południowego krańca Trupiej Blizny na tej wyspie. Odwiedź je, a jeśli jego duch udzieli ci błogosławieństwa, pozwolę ci wejść do Słonecznej Studni.', 'Odwiedź szczątki Thaloriena Szukającego Świtu i uzyskaj jego błogosławieństwo, by dzierżyć Quel\'Delar.', '', 'Wróć do Haldurona Jasnoskrzydłego w Wiosce Gwiazdy Zarannej na Wyspie Quel\'Danas.', 'Uzyskane błogosławieństwo Thaloriena', '', '', '', 0),
(24564, 'plPL', 'Oczyszczenie Quel\'Delara', 'Słoneczna Studnia i koniec wygnania Quel\'Delara czekają, $N.$B$BW środku zastaniesz Lor\'themara Therona, regenta Quel\'Thalas, i Wielkiego Magistra Rommatha. Miej się na baczności i nie daj się wciągnąć w ich polityczne intrygi.$B$BZamiast tego skup się na swoim zadaniu. Gdy będziesz $ggotów:gotowa; wejść do Słonecznej Studni, porozmawiaj ze Strażnikiem Słonecznej Studni. Zanurz przekuty Quel\'Delar w Słonecznej Studni, by dokończyć jego odnowę. Następnie pokaż ostrze Myralionowi Słonecznemu Żarowi przy Spoczynku Quel\'Delara.', 'Zanurz Zahartowany Quel\'Delar w Słonecznej Studni. Gdy będziesz $ggotów:gotowa; wejść na Płaskowyż Słonecznej Studni, porozmawiaj ze Strażnikiem Słonecznej Studni.$B', '', 'Wróć do Myraliona Słonecznego Żaru przy Spoczynku Quel\'Delara w Lodowej Koronie.', '', '', '', '', 0),
(24594, 'plPL', 'Oczyszczenie Quel\'Delara', 'Słoneczna Studnia i koniec wygnania Quel\'Delara czekają, $N.$B$BW środku zastaniesz Lor\'themara Therona, regenta Quel\'Thalas, i Wielkiego Magistra Rommatha. Miej się przed nimi na baczności i nie daj się wciągnąć w ich polityczne intrygi.$B$BZamiast tego skup się na swoim zadaniu. Porozmawiaj ze Strażnikiem Słonecznej Studni, by wejść na Płaskowyż Słonecznej Studni. Zanurz przekuty Quel\'Delar w Słonecznej Studni, by dokończyć jego odnowę. Gdy ostrze zostanie odnowione, pokaż je Myralionowi Słonecznemu Żarowi przy Spoczynku Quel\'Delara.', 'Zanurz Skażony Quel\'Delar w Słonecznej Studni. Gdy będziesz $ggotów:gotowa; wejść na Płaskowyż Słonecznej Studni, porozmawiaj ze Strażnikiem Słonecznej Studni.$B', '', 'Wróć do Myraliona Słonecznego Żaru przy Spoczynku Quel\'Delara w Lodowej Koronie.', '', '', '', '', 0),
(24595, 'plPL', 'Oczyszczenie Quel\'Delara', 'Przyznaję, wątpiłem, że naprawdę $gprzekułeś:przekułaś; Quel\'Delar, i nie spodziewałem się, że duch Thaloriena ci się objawi. Nie możesz pojąć, co dla mojego ludu znaczy odzyskanie Quel\'Delara.$B$BZgodnie z obietnicą wpuszczę cię do Słonecznej Studni, a w środku zastaniesz przywódców Srebrnej Luny. Zanieś miecz do komnaty Słonecznej Studni i zanurz go. Gdy ostrze zostanie odnowione, wróć z nim do Caladisa Jasnowłóczni przy Spoczynku Quel\'Delara.', 'Zanurz Skażony Quel\'Delar w Słonecznej Studni. Gdy będziesz $ggotów:gotowa; wejść na Płaskowyż Słonecznej Studni, porozmawiaj ze Strażnikiem Słonecznej Studni.', '', 'Wróć do Caladisa Jasnowłóczni przy Spoczynku Quel\'Delara w Lodowej Koronie.', '', '', '', '', 0),
(24596, 'plPL', 'Oczyszczenie Quel\'Delara', 'Słoneczna Studnia i koniec wygnania Quel\'Delara czekają, $N.$B$BW środku zastaniesz Lor\'themara Therona, regenta Quel\'Thalas, i Wielkiego Magistra Rommatha. Miej się przed nimi na baczności i nie daj się wciągnąć w ich polityczne intrygi.$B$BZamiast tego skup się na swoim zadaniu. Zanurz przekuty Quel\'Delar w Słonecznej Studni, by dokończyć jego odnowę, a potem porozmawiaj z Myralionem Słonecznym Żarem przy Spoczynku Quel\'Delara. Gdy będziesz $ggotów:gotowa; wejść na Płaskowyż Słonecznej Studni, porozmawiaj ze Strażnikiem Słonecznej Studni.', 'Zanurz Skażony Quel\'Delar w Słonecznej Studni. Gdy będziesz $ggotów:gotowa; wejść na Płaskowyż Słonecznej Studni, porozmawiaj ze Strażnikiem Słonecznej Studni.', '', 'Wróć do Myraliona Słonecznego Żaru przy Spoczynku Quel\'Delara w Lodowej Koronie.', '', '', '', '', 0),
(24598, 'plPL', 'Oczyszczenie Quel\'Delara', 'Słoneczna Studnia i koniec wygnania Quel\'Delara czekają, $N.$B$BW środku zastaniesz Lor\'themara Therona, regenta Quel\'Thalas, i Wielkiego Magistra Rommatha. Miej się przed nimi na baczności i nie daj się wciągnąć w ich polityczne intrygi.$B$BZamiast tego skup się na swoim zadaniu. Zanurz przekuty Quel\'Delar w Słonecznej Studni, by dokończyć jego odnowę, a potem pokaż go Myralionowi Słonecznemu Żarowi przy Spoczynku Quel\'Delara. Gdy będziesz $ggotów:gotowa; wejść na Płaskowyż Słonecznej Studni, porozmawiaj ze Strażnikiem Słonecznej Studni.', 'Zanurz Zahartowany Quel\'Delar w Słonecznej Studni. Gdy będziesz $ggotów:gotowa; wejść na Płaskowyż Słonecznej Studni, porozmawiaj ze Strażnikiem Słonecznej Studni.$B', '', 'Wróć do Myraliona Słonecznego Żaru przy Spoczynku Quel\'Delara w Lodowej Koronie.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(11488, 'plPL', 'To, co tu robimy, to nie twoja sprawa...', 0),
(11492, 'plPL', '<Larethor słucha uważnie, gdy opowiadasz o swoich czynach na Tarasie Magistrów.>$b$bBędzie nam brakowało Tyritha – porządny był z niego chłop. Dzięki tobie jednak jego śmierć nie poszła na marne.$b$bNie doceniłem cię. Przyjmij, proszę, to w imieniu Ofensywy Straceńczego Słońca – dar godny takiego bohatera jak ty.', 0),
(11496, 'plPL', 'Dobra robota, $N. Osłony powoli odzyskują moc. Sanktuarium będzie nasze w mgnieniu oka!', 0),
(11523, 'plPL', 'Dobra robota, $N. Osłony powoli odzyskują moc. Słoneczny Zasięg będzie nasz w mgnieniu oka!', 0),
(11524, 'plPL', 'Dobra robota, $N. Sanktuarium będzie nasze w mgnieniu oka!', 0),
(11525, 'plPL', 'Doskonale. Przeprogramowani wartownicy pomogą nam zabezpieczyć teren.', 0),
(11532, 'plPL', 'Masz prawdziwy talent, $gmłody:młoda;. Nie $gmyślałeś:myślałaś; kiedyś, żeby wstąpić do Podniebnej Straży?$b$bŻartuję, $N. Potrzebujemy cię tutaj, jeśli mamy w najbliższym czasie zdobyć doki.', 0),
(11533, 'plPL', 'Każdy demon zabity dziś to demon, z którym nie będziemy musieli walczyć jutro. Tak trzymaj.', 0),
(11535, 'plPL', 'Doskonale! Jesteśmy coraz bliżej...$b$bWkrótce będę mogła wykuć kowadło, a wtedy zacznie się prawdziwa praca.', 0),
(11536, 'plPL', 'Doskonale! Dzięki temu nasi żołnierze nie zostaną bez broni i pancerzy.$b$bTwoja pomoc naprawdę robi różnicę!', 0),
(11537, 'plPL', 'Twoje oddanie jest wzorowe, $N. Pokażemy siłom Płonącego Legionu, na co nas stać.', 0),
(11538, 'plPL', 'Twoje oddanie jest wzorowe, $N. W mgnieniu oka odbierzemy zbrojownię siłom Legionu!', 0),
(11539, 'plPL', 'Znakomita robota, $N. Armie Kaela zaczną się chwiać, a gdy zdobędziemy port, zadamy im śmiertelny cios!', 0),
(11540, 'plPL', 'Jakie myśli krążą po głowie księcia Kael\'thasa Słońcobieżcy, gdy słyszy o klęskach swoich armii?$b$bCzuje rozpacz? Bezradność? Strach?$b$bMam taką nadzieję.', 0),
(11541, 'plPL', 'Na dziś wystarczy. Kluczem jest tu powoli, a skutecznie. Zbyt duży zamęt i nagi zwróciłyby uwagę prosto na nas, a tego nie chcemy.$b$bWróć jutro, to popracujemy nad tym dalej.', 0),
(11542, 'plPL', 'Dobra robota, $N. Minie sporo czasu, zanim do portu dotrą jakiekolwiek posiłki.', 0),
(11543, 'plPL', 'Dobra robota, $N. Minie sporo czasu, zanim do portu dotrą jakiekolwiek posiłki.', 0),
(11545, 'plPL', 'Masz szlachetną duszę, $N. Łatwo zapomnieć o poległych pośród wojennej zawieruchy i euforii zwycięstwa. Przyjaciele i bliscy zmarłych dziękują ci.', 0),
(11546, 'plPL', 'Doskonale, $N.$b$bMam nadzieję, że pomoże ci to w twoich tutejszych staraniach.', 0),
(11547, 'plPL', 'Tak, tak. No to rzućmy okiem, dobrze?$b$bWszystko wydaje się w porządku. Bardzo dobrze. Oto twój translokator.$b$bJeśli któryś z twoich odczytów jest błędny, nie wiadomo, gdzie wylądujesz – i pamiętaj, będziesz $gmógł:mogła; winić tylko siebie.', 0),
(11548, 'plPL', 'Masz szlachetną duszę, $N. Łatwo zapomnieć o poległych pośród wojennej zawieruchy i euforii zwycięstwa. Przyjaciele i bliscy zmarłych dziękują ci.', 0),
(11549, 'plPL', 'Naprawdę jesteś hojną osobą i $ggodnym sojusznikiem:godną sojuszniczką;. Od tej pory będziesz $gznany:znana; jako $N ze Straceńczego Słońca, a wszyscy, którzy tu walczyli, poznają twoje czyny!', 0),
(11554, 'plPL', 'Twoja pomoc w ofensywie nie przeszła niezauważona, $N. Połączone siły Aldorów i Widzących składają ci podziękowania.', 0),
(11555, 'plPL', 'Wciąż dajesz się poznać w tej najważniejszej z bitew, $N. Przyjmij, proszę, to w dowód naszej nieustającej wdzięczności.', 0),
(11556, 'plPL', 'Bez ciebie nie doszlibyśmy tak daleko, $N. Połączona potęga Aldorów i Widzących nie wystarczy, by zmiażdżyć Legion i Kaela. Jesteśmy wdzięczni, że mamy wśród nas sojuszników twojego kalibru.', 0),
(11557, 'plPL', 'Należysz do naszych najlepszych, $N. Twoje imię jeszcze długo będzie znane w naszych szeregach. Przyjmij, proszę, ten skromny dar w imieniu naszych sił.', 0),
(14488, 'plPL', 'To, co tu robimy, to nie twoja sprawa...', 0),
(24522, 'plPL', 'Wpuścić cię do Słonecznej Studni? To niemożliwe! Słoneczna Studnia to najświętsze i najważniejsze miejsce naszego ludu. Dopiero niedawno odzyskaliśmy ją z pomocą Ofensywy Straceńczego Słońca. To nie miejsce dla turystów ani podróżnych.', 0),
(24535, 'plPL', 'Wyznam, że nie spodziewałem się, iż duch Thaloriena uzna cię za dziedzica Quel\'Delara, ale zdaję się na jego osąd. Możesz wejść do Słonecznej Studni, lecz przypominam, że jesteś gościem w naszym najświętszym przybytku i $gpowinieneś:powinnaś; się odpowiednio zachowywać.', 0),
(24553, 'plPL', 'To niewiarygodne, $N. Naprawdę ci się udało! Wszyscy quel\'dorei słyszeli o Thalorienie Szukającym Świtu i Quel\'Delarze, ale nikt nie przypuszczał, że miecz zostanie odnowiony.', 0),
(24562, 'plPL', 'Mam nadzieję, że rozumiesz, iż nie mogę tak po prostu wpuścić cię do Słonecznej Studni, $N. To najświętsze miejsce znane sin\'dorei, a dopiero niedawno odzyskaliśmy nad nim kontrolę.$B$BChcesz rozbudzać nadzieje naszego ludu opowieściami o Quel\'Delarze? Bez dowodu na prawdziwość twoich słów nie widzę powodu, by wierzyć ci na słowo.', 0),
(24563, 'plPL', 'Naprawdę nosisz Quel\'Delar. To wielki dzień dla całego Quel\'Thalas i dla sin\'dorei. Masz moje pozwolenie, by wejść do Słonecznej Studni i dokończyć odnowę miecza. Głowa do góry, $N. Dzieci Srebrnej Luny marzyły o tym dniu od lat.', 0),
(24564, 'plPL', 'Czy naprawdę widzę na własne oczy broń Thaloriena Szukającego Świtu? To cudowny dzień dla Słońcobójców i dla wszystkich sin\'dorei!', 0),
(24594, 'plPL', 'Czy naprawdę widzę na własne oczy broń Thaloriena Szukającego Świtu? To cudowny dzień dla Słońcobójców i dla wszystkich sin\'dorei!', 0),
(24595, 'plPL', 'To niewiarygodne, $N. Naprawdę ci się udało! Wszyscy quel\'dorei słyszeli o Thalorienie Szukającym Świtu i Quel\'Delarze, ale nikt nie przypuszczał, że miecz zostanie odnowiony.', 0),
(24596, 'plPL', 'Czy naprawdę widzę na własne oczy broń Thaloriena Szukającego Świtu? To cudowny dzień dla Słońcobójców i dla wszystkich sin\'dorei!', 0),
(24598, 'plPL', 'Czy naprawdę widzę na własne oczy broń Thaloriena Szukającego Świtu? To cudowny dzień dla Słońcobójców i dla wszystkich sin\'dorei!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(11458, 'plPL', '$GZrobiłeś:Zrobiłaś; to, o co prosiłem, $N?', 0),
(11488, 'plPL', 'Nie przypominam sobie, żebym zamawiał firmę sprzątającą... Ależ tak, jestem aptekarz Hummel.$B$B...Chwileczkę, co to ma znaczyć? Myślisz, że te bezwartościowe papiery mnie powstrzymają? Ha!', 0),
(11492, 'plPL', 'Cóż, $N, muszę przyznać, że nie byłem pewien, czy jeszcze cię zobaczę.$b$bJakie wieści przynosisz?', 0),
(11496, 'plPL', '$GReaktywowałeś:Reaktywowałaś; kryształowe osłony, $N?', 0),
(11523, 'plPL', '$GReaktywowałeś:Reaktywowałaś; kryształową osłonę, $N?', 0),
(11524, 'plPL', '$GPrzeprogramowałeś:Przeprogramowałaś; wartowników, $N?', 0),
(11525, 'plPL', '$GPrzeprogramowałeś:Przeprogramowałaś; wartowników, $N?', 0),
(11532, 'plPL', '$GWypełniłeś:Wypełniłaś; swoją misję, $N?', 0),
(11533, 'plPL', '$GWypełniłeś:Wypełniłaś; swoją misję, $N?', 0),
(11535, 'plPL', '$GZebrałeś:Zebrałaś; rudę, której potrzebuję?', 0),
(11536, 'plPL', '$GZebrałeś:Zebrałaś; rudę, o którą prosiłam?', 0),
(11537, 'plPL', 'Udało ci się, $N?', 0),
(11538, 'plPL', '$GZrobiłeś:Zrobiłaś; to, o co prosiłem, $N?', 0),
(11539, 'plPL', '$GZabiłeś:Zabiłaś; tę hołotę z Ostrza Świtu, $N?', 0),
(11540, 'plPL', '$GZabiłeś:Zabiłaś; tę hołotę z Ostrza Świtu, $N?', 0),
(11541, 'plPL', 'Moi zwiadowcy donoszą, że nagi nie zaznały dziś jeszcze dość zamętu.', 0),
(11542, 'plPL', '$GWykonałeś:Wykonałaś; swoje zadanie, $N?', 0),
(11543, 'plPL', '$GWykonałeś:Wykonałaś; swoje zadanie, $N?', 0),
(11545, 'plPL', 'Czy chcesz przekazać datek?', 0),
(11546, 'plPL', '$GZebrałeś:Zebrałaś; już te jagody?', 0),
(11547, 'plPL', '$GDostroiłeś:Dostroiłaś; już kryształ, $N?', 0),
(11548, 'plPL', 'Czy chcesz przekazać datek?', 0),
(11549, 'plPL', 'Czy jesteś $ggotów:gotowa; przekazać datek?', 0),
(24535, 'plPL', 'Czy $godwiedziłeś:odwiedziłaś; miejsce, w którym Thalorien poległ w obronie Słonecznej Studni?', 0),
(24553, 'plPL', 'Co się wydarzyło podczas twojego pobytu w Słonecznej Studni?', 0),
(24564, 'plPL', 'Co się wydarzyło w Słonecznej Studni?', 0),
(24594, 'plPL', '$GWróciłeś:Wróciłaś; ze Słonecznej Studni?', 0),
(24595, 'plPL', 'Opowiedz mi, co się wydarzyło w Słonecznej Studni, $N.', 0),
(24596, 'plPL', 'Co się wydarzyło podczas twojej wizyty w Słonecznej Studni?', 0),
(24598, 'plPL', 'Jakie wieści przynosisz ze Słonecznej Studni?', 0);
