INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
(37523, 0, 'plPL', 'Jestem $ggotów:gotowa; wejść do Słonecznej Studni.', ''),
(37552, 0, 'plPL', 'Zbadaj szczątki.', '');
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(37205, 1, 0, 'plPL', 'Rozkazuję wam wycofać się do samej Słonecznej Studni i pomóc w przygotowaniu obrony.'),
(37205, 2, 0, 'plPL', 'Ja stawię tu opór i zyskam dla was tyle czasu, ile zdołam. Wykorzystajcie go dobrze i przynieście chlubę naszemu księciu.'),
(37205, 3, 0, 'plPL', 'Walka u waszego boku w obronie naszej ziemi i naszego ludu była dla mnie wielkim zaszczytem.'),
(37205, 4, 0, 'plPL', 'Ty, $gnieznajomy:nieznajoma;! Nie jesteś jednym z moich żołnierzy! Zostaniesz i staniesz ze mną naprzeciw wroga?'),
(37205, 5, 0, 'plPL', 'Słuchajcie uważnie, plugawcy z Plagi! Żaden z was nie dotrze do Słonecznej Studni, póki ja stoję!'),
(37205, 6, 0, 'plPL', 'Ja... Nie miałem przeżyć tego ataku!'),
(37205, 9, 0, 'plPL', 'Nie wiem jak, ale ostrze wybrało cię na swego nowego właściciela. Weź je z moim błogosławieństwem i walcz nim z Plagą, jak ja niegdyś!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(20704, 'plPL', 'Baczność!', '', 0),
(23850, 'plPL', 'Witaj z powrotem, $n.', '', 0),
(24004, 'plPL', 'Precz, to miejsce jest nasze!', 'Precz, to miejsce jest nasze!', 0),
(24005, 'plPL', 'Moje! Nie zabierzesz tego miejsca!', 'Moje! Nie zabierzesz tego miejsca!', 0),
(24008, 'plPL', 'Wykryto przeciążenie rdzenia. Wykryto usterkę systemu...', 'Wykryto przeciążenie rdzenia. Ładowanie...', 0),
(24023, 'plPL', '', '$GWidziałeś:Widziałaś; uszkodzonych wartowników, którzy błąkają się po wyspie? Kilka modyfikacji kryształów sterujących ich zachowaniem pozwoli nam przejąć nad nimi kontrolę i użyć ich do zabezpieczenia kluczowych pozycji.$B$BSanktuarium Słonecznego Zasięgu będzie nasze w mgnieniu oka. Ten cel zrealizowaliśmy w $3244w procentach.', 0),
(24024, 'plPL', '', 'Udało nam się zdobyć Sanktuarium. Możemy dalej przeprogramowywać wartowników i wystawiać ich jako straże w innych kluczowych miejscach.', 0),
(24057, 'plPL', 'Niech błogosławieństwo naaru będzie z tobą, $gprzyjacielu:przyjaciółko;.', '', 0),
(24058, 'plPL', 'W moim fachu rzadko ma się okazję powąchać prochu. Służba tak blisko linii frontu, w strefie walk, to miła odmiana.', '', 0),
(24059, 'plPL', 'Skoro mowa o akcji – mam rozkaz przeprowadzić nalot.', 'Skoro mowa o akcji – mam rozkaz przeprowadzić nalot.', 0),
(24080, 'plPL', 'Zdobycie Sanktuarium Słonecznego Zasięgu było pierwszym krokiem naszego planu bitwy. Teraz mamy rozkaz przejąć kontrolę nad zbrojownią.$B$BNasz cel zrealizowaliśmy w $3233w procentach.', '', 0),
(24081, 'plPL', 'Przejęliśmy kontrolę nad zbrojownią, ale nasza praca na wyspie jeszcze się nie skończyła.', '', 0),
(24082, 'plPL', '', 'Mam rozkaz odwrócić uwagę wroga na Trupiej Bliźnie, żeby nasze siły mogły zdobyć Zbrojownię Słonecznego Zasięgu. Może to nie tak efektowne jak zabijanie demonów twarzą w twarz, ale jeśli dzięki temu wygramy tę bitwę, to jestem za.$B$BNasz cel zrealizowaliśmy w $3233w procentach.', 0),
(24083, 'plPL', '', 'Zdobyliśmy zbrojownię, $n. Nie spoczywajmy jednak na laurach. Legion na pewno tego nie zrobi.', 0),
(24086, 'plPL', '$n, jak dobrze znów cię widzieć!', '$n, jak dobrze znów cię widzieć!', 0),
(24087, 'plPL', 'Patrzcie wszyscy, to $n!', 'Patrzcie wszyscy, to $n!', 0),
(24088, 'plPL', 'Strzeżcie się, Ostrze Świtu, demony i nagi – $n $gwrócił:wróciła;!', 'Strzeżcie się, Ostrze Świtu, demony i nagi – $n $gwrócił:wróciła;!', 0),
(24089, 'plPL', '$GPanie:Pani;, $n, mamy szczęście, że jesteś tu z nami.', '$GPanie:Pani;, $n, mamy szczęście, że jesteś tu z nami.', 0),
(24098, 'plPL', 'Ofensywa Straceńczego Słońca ma szczęście, że $n jest po naszej stronie.', 'Ofensywa Straceńczego Słońca ma szczęście, że $n jest po naszej stronie.', 0),
(24099, 'plPL', 'Gdyby nie $n, wszyscy dawno byśmy już nie żyli.', 'Gdyby nie $n, wszyscy dawno byśmy już nie żyli.', 0),
(24100, 'plPL', '$n, jeszcze raz dziękuję za pomoc. Bez ciebie nie osiągnęlibyśmy niczego z tego wszystkiego.', '$n, jeszcze raz dziękuję za pomoc. Bez ciebie nie osiągnęlibyśmy niczego z tego wszystkiego.', 0),
(24102, 'plPL', 'Niech żyje $n! Hip, hip, hurra!', 'Niech żyje $n! Hip, hip, hurra!', 0),
(24103, 'plPL', 'Służba u twojego boku to zaszczyt, $n.', 'Służba u twojego boku to zaszczyt, $n.', 0),
(24106, 'plPL', 'Gdybym była jednym z tych krwawych elfów z Ostrza Świtu, już bym odpływała z wyspy, skoro $n tu jest.', 'Gdybym była jednym z tych krwawych elfów z Ostrza Świtu, już bym odpływała z wyspy, skoro $n tu jest.', 0),
(24107, 'plPL', 'Jak myślicie, ilu Nędznych $n już $guwolnił:uwolniła; od cierpień?', 'Jak myślicie, ilu Nędznych $n już $guwolnił:uwolniła; od cierpień?', 0),
(24108, 'plPL', 'Baczność! Przybywa $n, $gjeden:jedna; z naszych najlepszych!', 'Baczność! Przybywa $n, $gjeden:jedna; z naszych najlepszych!', 0),
(24110, 'plPL', 'Witaj z powrotem, $n.', 'Witaj z powrotem, $n.', 0),
(24111, 'plPL', 'Oto $gnasz bohater:nasza bohaterka;! Jak się masz, $n?', 'Oto $gnasz bohater:nasza bohaterka;! Jak się masz, $n?', 0),
(24112, 'plPL', 'Daję głowę, że gdyby nie $n, cała ta ofensywa zakończyłaby się klęską.', 'Daję głowę, że gdyby nie $n, cała ta ofensywa zakończyłaby się klęską.', 0),
(24113, 'plPL', 'Cokolwiek się stanie, twoje zasługi zawsze będą tu wywyższane, $n!', 'Cokolwiek się stanie, twoje zasługi zawsze będą tu wywyższane, $n!', 0),
(24115, 'plPL', '$GSiałeś:Siałaś; ostatnio spustoszenie wśród demonów na Trupiej Bliźnie, $n?', '$GSiałeś:Siałaś; ostatnio spustoszenie wśród demonów na Trupiej Bliźnie, $n?', 0),
(24116, 'plPL', '$n, któregoś dnia muszę ci postawić kolejkę.', '$n, któregoś dnia muszę ci postawić kolejkę.', 0),
(24117, 'plPL', 'Nawet nie chcę myśleć, co by się tu stało, gdyby $n kiedyś $gpostanowił:postanowiła; nie wracać.', 'Nawet nie chcę myśleć, co by się tu stało, gdyby $n kiedyś $gpostanowił:postanowiła; nie wracać.', 0),
(24119, 'plPL', '$n, nie masz pojęcia, jaka to ulga cię widzieć!', '$n, nie masz pojęcia, jaka to ulga cię widzieć!', 0),
(24120, 'plPL', 'Co za zbieg okoliczności... właśnie o tobie rozmawialiśmy, $n!', 'Co za zbieg okoliczności... właśnie o tobie rozmawialiśmy, $n!', 0),
(24121, 'plPL', 'Kto potrzebuje wartowników? $n tu jest!', 'Kto potrzebuje wartowników? $n tu jest!', 0),
(24122, 'plPL', 'Hej, $n, zostaw trochę chwały dla nas, co?', 'Hej, $n, zostaw trochę chwały dla nas, co?', 0),
(24151, 'plPL', '', 'Zdobyliśmy port, a ten statek to miły dodatek. Szkoda tylko, że jeszcze nie nadaje się do żeglugi.$B$BTymczasem polecono mi nadzorować sianie zamętu wśród nag na Wybrzeżu Zielonoskrzelnych.$B$BMyślisz, że mi pomożesz?', 0),
(24152, 'plPL', 'Muszę przechwycić posiłki Ostrza Świtu.', 'Muszę przechwycić posiłki Ostrza Świtu.', 0),
(24173, 'plPL', 'Smoczy jastrząb nadlatuje z zachodu! Zestrzelcie go!', '', 0),
(24175, 'plPL', 'Hołota ze Straceńczego Słońca! Ognia według uznania!', '', 0),
(24184, 'plPL', 'Skupcie się na demonach. Dziś nie zależy nam na zabijaniu Plagi.', 'Skupcie się na demonach. Dziś nie zależy nam na zabijaniu Plagi.', 0),
(24195, 'plPL', 'Witajcie, rekruci. Jestem instruktor musztry Bahduum. Przez najbliższe kilka dni przejdziecie szkolenie wprowadzające.', '', 0),
(24196, 'plPL', 'Wyspę Quel\'Danas opanowały siły księcia Kael\'thasa Słońcobieżcy. Wywiad uznał go za martwego. Wywiad się mylił.', '', 0),
(24197, 'plPL', 'Na płaskowyżu on i jego demoniczni kumple próbują na nowo rozpalić Słoneczną Studnię i otworzyć wyrwę, by sprowadzić z powrotem na świat swojego szefa, Kil\'jaedena.', '', 0),
(24198, 'plPL', 'Naszym zadaniem jest wybić jak najwięcej jego mięsa armatniego i wspierać specjalistów, których sprowadzają tu nasi przełożeni.', '', 0),
(24199, 'plPL', 'Nie muszę mówić, że wielu z nas nie wróci do domu. Ale jeśli będziecie pamiętać o szkoleniu i zachowacie trzeźwy umysł, znacznie zwiększycie swoje szanse.', '', 0),
(24200, 'plPL', 'Na razie to wszystko. Bądźcie czujni, chłopcy i dziewczęta.', '', 0),
(24210, 'plPL', 'Dobra, cisza. Mamy mnóstwo roboty i bardzo mało czasu, ludzie.', '', 0),
(24211, 'plPL', 'Z niektórymi z was, draenei, stałem już ramię w ramię w Skettis, a z innymi w Dolinie Cienistego Księżyca. Ale teraz jesteśmy w Azeroth, a sytuacja wygląda ponuro.', '', 0),
(24212, 'plPL', 'Najpierw jednak wy, sin\'dorei, słuchajcie uważnie. U mnie panuje dyscyplina... to nie będzie to, do czego przywykliście u Widzących. Róbcie swoje albo wracajcie na łódź!', '', 0),
(24213, 'plPL', 'Skoro to mamy już za sobą, witajcie na Wyspie Quel\'Danas. Słoneczna Studnia jest na płaskowyżu na południu, a książę Kael\'thas zaszył się na Tarasie Magistrów na wschodzie.', '', 0),
(24214, 'plPL', 'Jesteśmy tu jako wsparcie dla tak zwanych „poszukiwaczy przygód”, których wezwała wierchuszka. Pomożemy im utrzymać kluczowe punkty na wyspie i odciągniemy od nich uwagę wroga, żeby mogli robić swoje.', '', 0),
(24215, 'plPL', 'Jeśli żadna z was, panienki, nie ma pytań, dalsze instrukcje i przydziały dostaniecie od dowódców drużyn. To wszystko. Powodzenia!', '', 0),
(24216, 'plPL', 'Witajcie przy Słonecznej Studni. Mimo łagodnych temperatur i malowniczych widoków nie jesteście na wakacjach, panie i panowie!', '', 0),
(24217, 'plPL', 'Obecna sytuacja wygląda tak: trzymamy, co się da, a ci z większym doświadczeniem i lepszym sprzętem ruszają na księcia Kael\'thasa.', '', 0),
(24218, 'plPL', 'Wiem, też myśleliśmy, że nie żyje, ale tak nie jest. Próbuje użyć Słonecznej Studni, by sprowadzić na ten świat władcę Płonącego Legionu, Kil\'jaedena.', '', 0),
(24219, 'plPL', 'Zapewniam was, ludzie, że jeśli mu się uda, ten świat ucierpi o wiele bardziej niż kiedykolwiek Rubież! Dopilnujmy więc, żeby do tego nie doszło.', '', 0),
(24220, 'plPL', 'Wojownicy zostaną wysłani do utrzymania kluczowych pozycji, a wy, strzelcy, dostaniecie przydział do trzymania z dala wrogich lotników.', '', 0),
(24221, 'plPL', 'Czekam na rozkazy w sprawie waszych konkretnych przydziałów. Tymczasem zostańcie tutaj i bądźcie gotowi wyruszyć w każdej chwili!', '', 0),
(24264, 'plPL', 'Niemal umocniliśmy kontrolę nad Słonecznym Zasięgiem. Jeśli nie dopuścimy żadnych posiłków do portu, na pewno nam się uda.$B$BNasz cel zrealizowaliśmy w $3238w procentach.', '', 0),
(24266, 'plPL', 'Udało się, $n. Słoneczny Zasięg jest pod naszą kontrolą, a od całkowitego zwycięstwa dzielą nas zaledwie chwile.', '', 0),
(24267, 'plPL', '', 'Zbieram fundusze na budowę pomnika ku czci poległych w wojnie. Nie wolno nam zapominać o ofiarach, jakie ponieśliśmy, by odnieść zwycięstwo.$B$BTen cel zrealizowaliśmy w $3275w procentach.', 0),
(24268, 'plPL', '', 'Czyż pomnik nie jest piękny? Trzeba pamiętać te chwile w naszej historii, gdy składano wielkie ofiary, byśmy nie zapomnieli o cenie każdej wojny – nawet tej wygranej.', 0),
(24302, 'plPL', '', 'Nie ruszaj na wroga $gnieprzygotowany:nieprzygotowana;, $n. Mogę ci zapewnić bardzo potężne przedmioty... pod warunkiem, że $gdowiodłeś:dowiodłaś; nam swojej wartości.', 0),
(24303, 'plPL', 'Sługusy Kaela zaraz dostaną lekcję pokory. Zmiażdżymy armię Ostrza Świtu i odbierzemy im Port Słonecznego Zasięgu.$B$BNasz cel zrealizowaliśmy w $3238w procentach.', '', 0),
(24304, 'plPL', 'Słoneczny Zasięg jest nasz. Psy Kaela uciekają... czas skrócić ich męki!', '', 0),
(24425, 'plPL', 'Do ataku!', '', 0),
(24453, 'plPL', '<Smoczy jastrząb wydaje się zaniepokojony zamieszaniem w okolicy.>', '', 0),
(24459, 'plPL', '<Leć smoczym jastrzębiem do Słonecznego Zasięgu.>', '<Leć smoczym jastrzębiem do Słonecznego Zasięgu.>', 0),
(25088, 'plPL', '', 'Czy wiesz, że alchemicy potrafią transmutować niektóre klejnoty? Rozmawiałyśmy o tym z Mar\'nah.$B$BJestem przekonana, że przy jej biegłości, gdy tylko jej pracownia będzie gotowa, zdołamy razem tworzyć klejnoty, które uważano za zaginione w mrokach czasu.', 0),
(25089, 'plPL', '', 'Udało się nam, $n. Mar\'nah nauczyła się transmutować bardzo szczególne klejnoty. A ja nauczyłam się je obrabiać.', 0),
(25091, 'plPL', 'Nie lękaj się. Nasze cele są te same.', '', 0),
(25560, 'plPL', 'Co cię sprowadza do Słonecznej Studni?', 'Co cię sprowadza do Słonecznej Studni?', 0),
(26245, 'plPL', 'Baczność!', '', 0),
(37148, 'plPL', 'To zapewne szczątki Thaloriena Szukającego Świtu, ostatniego właściciela Quel\'Delara.', '', 0),
(37154, 'plPL', 'Musimy za wszelką cenę bronić Słonecznej Studni przed wrogiem.', '', 0),
(37197, 'plPL', 'Dlaczego to się stało? Czemu tu $gprzybyłeś:przybyłaś;?', '', 0),
(37198, 'plPL', 'To Quel\'Delar! Masz ten miecz!', '', 0),
(37465, 'plPL', 'Wiedziałem, że to ostrze wykute przez smoki, gdy tylko je ujrzałem.', '', 0),
(37466, 'plPL', 'Ale czy to możliwe? Czy to naprawdę...', '', 0),
(37469, 'plPL', 'Styl tego ostrza i jego znaki sugerowały, że może to być miecz wykuty przez smoki. Wreszcie poznamy odpowiedź.', '', 0),
(37470, 'plPL', 'Po tylu latach, czy to naprawdę może być...', '', 0),
(37514, 'plPL', 'To na nas spoczywa odnowienie Quel\'Delara dla Słońcobójców.', '', 0),
(37518, 'plPL', 'Przysięgam, że Srebrny Sojusz doprowadzi do odnowienia Quel\'Delara.', '', 0),
(37804, 'plPL', 'Gdy będziesz $ggotów:gotowa;, wprowadzę cię do Słonecznej Studni.', 'Gdy będziesz $ggotów:gotowa;, wprowadzę cię do Słonecznej Studni.', 0);
